import{storage}from'./storage';import type{CafeDatabase,CreateOrderInput,Order}from'@/types/cafe';export interface CafeRepository{getMenu():Promise<CafeDatabase>;createOrder(input:CreateOrderInput):Promise<Order>;getOrder(id:string):Promise<Order|null>}
const delay=(ms:number)=>new Promise(r=>setTimeout(r,ms));export class LocalCafeRepository implements CafeRepository{async getMenu(){return storage.readDatabase()}async createOrder(input:CreateOrderInput){await delay(250);const db=storage.readDatabase(),existing=db.orders.find(x=>x.clientToken===input.clientToken);if(existing)return existing;const order:Order={id:`o${Date.now()}`,ref:`ORD-${db.seq||2073}`,ts:Date.now(),status:'new',...input};db.orders.unshift(order);db.seq=(db.seq||2073)+1;storage.writeDatabase(db);return order}async getOrder(id:string){return storage.readDatabase().orders.find(x=>x.id===id)??null}}
export class HttpCafeRepository implements CafeRepository{constructor(private readonly baseUrl:string){}private async request<T>(path:string,init?:RequestInit):Promise<T>{const response=await fetch(`${this.baseUrl}${path}`,{...init,headers:{'Content-Type':'application/json',...init?.headers}});if(!response.ok)throw new Error(`API request failed: ${response.status}`);return response.json()as Promise<T>}getMenu(){return this.request<CafeDatabase>('/menu')}createOrder(input:CreateOrderInput){return this.request<Order>('/orders',{method:'POST',body:JSON.stringify(input)})}getOrder(id:string){return this.request<Order|null>(`/orders/${encodeURIComponent(id)}`)}}
export const cafeRepository:CafeRepository=import.meta.env.VITE_USE_MOCK_API!=='false'?new LocalCafeRepository():new HttpCafeRepository(import.meta.env.VITE_API_BASE_URL??'/api')
