import{seed,STORAGE_KEY}from'@/constants/menu';import type{CafeDatabase,CartState}from'@/types/cafe';const CART_KEY='samicafe_cart_v2';const clone=<T>(v:T):T=>JSON.parse(JSON.stringify(v)) as T;export const storage={readDatabase():CafeDatabase{try{const v=JSON.parse(localStorage.getItem(STORAGE_KEY)??'null')as CafeDatabase;if(v?.cats&&v?.drinks&&v?.orders)return v}catch{}return clone(seed)as CafeDatabase},writeDatabase(v:CafeDatabase){localStorage.setItem(STORAGE_KEY,JSON.stringify(v))},readCart():CartState|null{try{return JSON.parse(localStorage.getItem(CART_KEY)??'null')as CartState|null}catch{return null}},writeCart(v:CartState){localStorage.setItem(CART_KEY,JSON.stringify(v))},clearCart(){localStorage.removeItem(CART_KEY)}}
