import{computed,reactive,ref,watch}from'vue';import{defineStore}from'pinia';import{cafeRepository}from'@/services/cafeRepository';import{storage}from'@/services/storage';import type{CafeDatabase,Drink,Order,OrderItem}from'@/types/cafe';
export const useCafe=defineStore('cafe',()=>{const persisted=storage.readCart(),db=ref<CafeDatabase>(storage.readDatabase()),cart=reactive<Record<string,number>>(persisted?.quantities??{}),notes=ref(persisted?.notes??''),table=ref(Number(new URLSearchParams(location.search).get('table'))||persisted?.table||1),loading=ref(false),submitting=ref(false),error=ref<string|null>(null);const categories=computed(()=>db.value.cats.filter(x=>x.on)),drinks=computed(()=>db.value.drinks),items=computed(()=>Object.entries(cart).map(([id,q])=>({drink:drinks.value.find(x=>x.id===id),q})).filter((x):x is{drink:Drink;q:number}=>Boolean(x.drink))),count=computed(()=>items.value.reduce((s,x)=>s+x.q,0)),total=computed(()=>items.value.reduce((s,x)=>s+x.q*x.drink.pr,0));watch([()=>({...cart}),notes,table],()=>storage.writeCart({quantities:{...cart},notes:notes.value,table:table.value}),{deep:true});async function load(){loading.value=true;error.value=null;try{db.value=await cafeRepository.getMenu()}catch{error.value='تعذر تحميل القائمة. تحقق من اتصال الإنترنت.'}finally{loading.value=false}}function add(id:string){cart[id]=(cart[id]??0)+1}function remove(id:string){const next=(cart[id]??0)-1;if(next<=0)delete cart[id];else cart[id]=next}function setTable(n:number){if(!db.value.tables.some(x=>x.n===n&&x.on))return;table.value=n;history.replaceState(null,'',`?table=${n}`)}async function placeOrder():Promise<Order>{if(submitting.value)throw new Error('ORDER_IN_PROGRESS');if(!count.value)throw new Error('EMPTY_CART');submitting.value=true;error.value=null;try{const payload:OrderItem[]=items.value.map(x=>({id:x.drink.id,n:x.drink.n,q:x.q,pr:x.drink.pr,img:x.drink.img}));return await cafeRepository.createOrder({table:table.value,items:payload,notes:notes.value.trim(),clientToken:crypto.randomUUID()})}catch(e){error.value='تعذر إرسال الطلب. حاول مرة أخرى.';throw e}finally{submitting.value=false}}async function getOrder(id:string){return cafeRepository.getOrder(id)}function reset(){Object.keys(cart).forEach(k=>delete cart[k]);notes.value='';storage.clearCart()}return{db,cart,notes,table,loading,submitting,error,categories,drinks,items,count,total,load,add,remove,setTable,placeOrder,getOrder,reset}})
